# Prompt (summary): Run compiler e2e fixtures comparing stdout and exit code with diffs and leak check.
# Changes: added file.
"""Run end-to-end compiler fixtures and print a clean summary.

Each case is a directory tests/e2e/<name>/ holding:
    source        bytes fed to the compiler on stdin (required)
    expected.out  exact expected bytes on stdout (default: empty)
    expected.exit expected exit code as text (default: 0)

Usage:
    python scripts/run_e2e.py [--valgrind | --no-valgrind]
        [--timeout SECS] [--verbose]

Compiler (Makefile DEBUG_BIN) and cases come from hardcoded paths below.

Exit code is 0 only when every case matches and no leaks are reported.
"""

import argparse
import difflib
import os
import platform
import re
import shutil
import signal
import subprocess
import sys
import tempfile


def _use_color():
    if os.environ.get("FORCE_COLOR"):
        return True
    if os.environ.get("NO_COLOR"):
        return False
    try:
        return sys.stdout.isatty()
    except (OSError, ValueError):
        return False


_COLOR = _use_color()


def _paint(code, text):
    return f"\x1b[{code}m{text}\x1b[0m" if _COLOR else text


def _tag(status):
    if status == "PASS":
        return _paint("32", "[PASS]")
    if status in ("FAIL", "TIMEOUT"):
        return _paint("31", f"[{status}]")
    return f"[{status}]"


_WIN_FATAL = {
    0xC0000005: "ACCESS_VIOLATION",
    0xC00000FD: "STACK_OVERFLOW",
    0xC0000094: "INT_DIVIDE_BY_ZERO",
}


def _crash_name(returncode):
    """Name a fatal exit code, or None if the process exited normally."""
    if returncode < 0:
        try:
            return signal.Signals(-returncode).name
        except ValueError:
            return f"signal {-returncode}"
    if returncode >= 0xC0000000:
        return _WIN_FATAL.get(returncode, f"NTSTATUS 0x{returncode:08X}")
    return None


def _print_diff(diff_text):
    for line in diff_text.splitlines():
        stripped = line.lstrip()
        if stripped.startswith("-"):
            print(_paint("31", line))
        elif stripped.startswith("+"):
            print(_paint("32", line))
        elif stripped.startswith("@@"):
            print(_paint("36", line))
        else:
            print(line)

VALGRIND_FLAGS = [
    "--leak-check=full",
    "--show-leak-kinds=all",
    "--track-origins=yes",
    # NOTE: no --errors-for-leaks (unknown to old valgrind); leaks are
    # detected by parsing byte counts from the log instead.
    # 100, not 99: exit code 99 is a valid IFJ26 compiler result
    # (internal error), so valgrind must not reuse it here.
    "--error-exitcode=100",
]
VALGRIND_ERROR_EXIT = 100
LEAK_RE = re.compile(
    r"(definitely|indirectly|possibly|still reachable) lost: ([\d,]+) bytes"
)
FRAME_RE = re.compile(r"==\d+==\s+(?:at|by) 0x[0-9A-Fa-f]+: (\S+) \(([^()]+)\)")
# Valgrind frames that never point at user code.
_NON_USER_FILES = ("vg_replace_malloc.c", "snow.h")
DIFF_CONTEXT_LINES = 20


_OS_DIR = os.path.join("build", platform.system().lower())
COMPILER = os.path.join(_OS_DIR, "debug", "ifj26")
CASES_DIR = "tests/e2e"


def find_compiler(path):
    if os.path.isfile(path) and os.access(path, os.X_OK):
        return path
    if os.path.isfile(path + ".exe"):
        return path + ".exe"
    return None


def discover_cases(cases_dir):
    cases = []
    for entry in sorted(os.listdir(cases_dir)):
        case_dir = os.path.join(cases_dir, entry)
        source = os.path.join(case_dir, "source")
        if os.path.isdir(case_dir) and os.path.isfile(source):
            cases.append((entry, case_dir))
    return cases


def read_case(case_dir):
    with open(os.path.join(case_dir, "source"), "rb") as handle:
        source = handle.read()
    expected_out = b""
    out_path = os.path.join(case_dir, "expected.out")
    if os.path.isfile(out_path):
        with open(out_path, "rb") as handle:
            expected_out = handle.read()
    expected_exit = 0
    exit_path = os.path.join(case_dir, "expected.exit")
    if os.path.isfile(exit_path):
        with open(exit_path, "r") as handle:
            expected_exit = int(handle.read().strip() or "0")
    return source, expected_out, expected_exit


def text_diff(expected, actual, limit=DIFF_CONTEXT_LINES):
    exp_lines = expected.decode("utf-8", errors="replace").splitlines()
    act_lines = actual.decode("utf-8", errors="replace").splitlines()
    diff = difflib.unified_diff(exp_lines, act_lines, "expected", "actual", lineterm="")
    lines = list(diff)[:limit]
    if not lines:
        return ""
    return "\n".join("    " + line for line in lines)


def _leak_site(log):
    """File:line of the first user-code frame in a leak record, if any."""
    for line in log.splitlines():
        match = FRAME_RE.search(line)
        if not match:
            continue
        _func, where = match.group(1), match.group(2).strip()
        if where.startswith("in ") or ":" not in where:
            continue
        if os.path.basename(where.split(":")[0]) in _NON_USER_FILES:
            continue
        return where
    return None


def parse_valgrind_log(log_path):
    """Return (leaked_bytes, detail); None bytes means the log is unusable."""
    try:
        with open(log_path, "r", errors="replace") as handle:
            log = handle.read()
    except OSError:
        return None, "unreadable log"
    if "definitely lost:" not in log and "no leaks are possible" not in log:
        return None, "no leak summary in log"
    total = 0
    kinds = []
    for match in LEAK_RE.finditer(log):
        nbytes = int(match.group(2).replace(",", ""))
        total += nbytes
        if nbytes > 0:
            kinds.append(f"{match.group(1)} lost: {nbytes}B")
    if total == 0:
        return 0, "none"
    site = _leak_site(log)
    detail = ", ".join(kinds)
    if site is not None:
        detail += f" @ {site}"
    return total, detail


def run_one(name, case_dir, compiler, use_valgrind, timeout, log_dir):
    source, expected_out, expected_exit = read_case(case_dir)
    command = [compiler]
    log_path = None
    if use_valgrind:
        log_path = os.path.join(log_dir, name + ".valgrind.log")
        command = (
            ["valgrind"]
            + VALGRIND_FLAGS
            + ["--log-file=" + log_path]
            + command
        )
    try:
        proc = subprocess.run(
            command,
            input=source,
            capture_output=True,
            timeout=timeout,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return {
            "name": name,
            "status": "FAIL",
            "leaked": False,
            "info": f"timed out after {timeout}s",
            "diff": "",
        }
    actual_exit = proc.returncode
    actual_out = proc.stdout or b""
    leaked = False
    leak_info = ""
    if use_valgrind:
        if actual_exit == VALGRIND_ERROR_EXIT:
            # Valgrind masks the compiler exit code on errors, so the
            # exit-code check below is skipped.
            exit_ok = True
        else:
            exit_ok = actual_exit == expected_exit
        leak_bytes, detail = parse_valgrind_log(log_path)
        if leak_bytes is None:
            leaked, leak_info = True, detail
        elif leak_bytes > 0:
            leaked, leak_info = True, f"{leak_bytes}B ({detail})"
        if actual_exit == VALGRIND_ERROR_EXIT and not leaked:
            leaked, leak_info = True, "valgrind reported errors"
    else:
        exit_ok = actual_exit == expected_exit
    out_ok = actual_out == expected_out
    if leaked or not exit_ok or not out_ok:
        status = "FAIL"
    else:
        status = "PASS"
    info = (
        f"exit {actual_exit} (want {expected_exit}), "
        f"{len(actual_out)}/{len(expected_out)} output bytes"
    )
    crash = _crash_name(actual_exit)
    if crash is not None:
        info = f"crashed ({crash}), " + info
    if use_valgrind:
        info += ", leaks: %s" % (leak_info if leaked else "none")
    diff = ""
    if status == "FAIL" and not out_ok:
        diff = text_diff(expected_out, actual_out)
    elif status == "FAIL" and not exit_ok and not use_valgrind:
        diff = ""
    return {
        "name": name,
        "status": status,
        "leaked": leaked,
        "info": info,
        "diff": diff,
    }


def main(argv=None):
    parser = argparse.ArgumentParser(description="Run compiler e2e cases.")
    parser.add_argument(
        "--exclude",
        action="append",
        default=[],
        help="skip this case name (repeatable)",
    )
    parser.add_argument(
        "--only",
        action="append",
        default=[],
        help="run only this case name (repeatable)",
    )
    parser.add_argument(
        "--valgrind", dest="valgrind", action="store_true", default=True
    )
    parser.add_argument("--no-valgrind", dest="valgrind", action="store_false")
    parser.add_argument("--timeout", type=int, default=10)
    parser.add_argument("--verbose", action="store_true")
    args = parser.parse_args(argv)

    compiler = find_compiler(COMPILER)
    if compiler is None:
        print(f"FAIL: compiler binary '{COMPILER}' not found")
        return 2
    if not os.path.isdir(CASES_DIR):
        print(f"FAIL: cases directory '{CASES_DIR}' not found")
        return 2
    cases = discover_cases(CASES_DIR)
    if args.only:
        wanted = set(args.only)
        cases = [(n, d) for n, d in cases if n in wanted]
    if args.exclude:
        skipped = set(args.exclude)
        cases = [(n, d) for n, d in cases if n not in skipped]
    if not cases:
        print(f"FAIL: no cases selected in '{CASES_DIR}'")
        return 2

    use_valgrind = args.valgrind
    if use_valgrind and shutil.which("valgrind") is None:
        print(_paint("33", "WARN: valgrind not found, running without leak check"))
        use_valgrind = False

    results = []
    with tempfile.TemporaryDirectory(prefix="e2e_valgrind_") as log_dir:
        for name, case_dir in cases:
            result = run_one(
                name,
                case_dir,
                compiler,
                use_valgrind,
                args.timeout,
                log_dir,
            )
            results.append(result)
            print(
                "{} {} ({})".format(
                    _tag(result["status"]), result["name"], result["info"]
                )
            )
            if result["diff"]:
                _print_diff(result["diff"])

    passed = sum(1 for r in results if r["status"] == "PASS")
    leaked = sum(1 for r in results if r["leaked"])
    if use_valgrind:
        summary = f"e2e: {passed}/{len(results)} passed, {leaked} with leaks"
    else:
        summary = f"e2e: {passed}/{len(results)} passed"
    print(_paint("32" if passed == len(results) else "31", summary))
    return 0 if passed == len(results) else 1


if __name__ == "__main__":
    sys.exit(main())
